import{_ as p,o as e,c as t,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const D=JSON.parse('{"title":"电容引起的时间延迟","description":"","frontmatter":{},"headers":[],"relativePath":"notes/《信号完整性》学习笔记/20-电容引起的时间延迟.md","filePath":"notes/《信号完整性》学习笔记/20-电容引起的时间延迟.md","lastUpdated":1794229129000}'),o={name:"notes/《信号完整性》学习笔记/20-电容引起的时间延迟.md"};function s(l,a,n,c,d,i){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="电容引起的时间延迟" tabindex="-1">电容引起的时间延迟 <a class="header-anchor" href="#电容引起的时间延迟" aria-label="Permalink to &quot;电容引起的时间延迟&quot;">​</a></h1><h2 id="一容性负载与信号到达时间" tabindex="-1">一、容性负载与信号到达时间 <a class="header-anchor" href="#一容性负载与信号到达时间" aria-label="Permalink to &quot;一、容性负载与信号到达时间&quot;">​</a></h2><p>容性负载不同的时候，信号波形到达负载的时间可能也不同。</p><p>容性负载在链路末端的时候，比较典型的就是点对点互连这种拓扑结构。</p><p>输入芯片的负载有一定的输入电容。输入电容不同，信号边沿到达芯片的时间也不一样。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794208750664-44bb5c4f-aa8c-424d-8f8f-26ae0dab7bde.svg" alt="末端容性负载的互连结构"></p><h2 id="二末端电容的-rc-充电" tabindex="-1">二、末端电容的 RC 充电 <a class="header-anchor" href="#二末端电容的-rc-充电" aria-label="Permalink to &quot;二、末端电容的 RC 充电&quot;">​</a></h2><p>不考虑反射的影响：</p><p>源端是匹配的，输出阻抗 50 Ω，传输线的阻抗也是 50 Ω；</p><p>末端有一个 2 pF 的电容、容性负载，末端还给了它一个 50 Ω 的匹配电阻。这个的意思其实就是不考虑反射的影响，单纯考虑这个电容对信号边沿到达时间的影响是什么样子。</p><p>信号到达电容的时候，这是一个电容充电电路，RC 充电。假如不考虑这个 50 Ω 匹配电阻，实际上就是一个 RC 充电电路。</p><p>电容两端电压呈指数变化。这个指数变化的情况和时间常数有关。电容值不同，上升边沿肯定不一样。时间常数越大，充电时间就越长，边沿就会越缓慢。</p><p>从这个 RC 电路的特性来说，就能粗略判断：电容越大，边沿越缓。</p><h2 id="三无容性负载与-2-4-8-pf-的上升曲线" tabindex="-1">三、无容性负载与 2 / 4 / 8 pF 的上升曲线 <a class="header-anchor" href="#三无容性负载与-2-4-8-pf-的上升曲线" aria-label="Permalink to &quot;三、无容性负载与 2 / 4 / 8 pF 的上升曲线&quot;">​</a></h2><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794208751498-734c24a2-32eb-4d02-9620-0a7e8bcea11c.svg" alt="末端容性负载不同的上升曲线"></p><p>红色这条线是末端没有容性负载的时候；蓝色这条线，末端容性负载 2 pF；粉色这条线，末端容性负载 4 pF；绿色这条线，末端容性负载 8 pF。这几条曲线的边沿不一样。</p><p>判断信号到达时间，假如以中值电平来判断，现在是 1 V，用 0.5 V 来判断的话，这几种情况下信号到达的时间明显不同，差了近百 ps。</p><h2 id="四线路中间电容与信号延迟" tabindex="-1">四、线路中间电容与信号延迟 <a class="header-anchor" href="#四线路中间电容与信号延迟" aria-label="Permalink to &quot;四、线路中间电容与信号延迟&quot;">​</a></h2><p>容性负载在线路中间的时候，对接收端接收到的信号波形的延迟时间也会有影响。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794208751037-77e65513-254d-4a4d-9adc-9045c2d3d58f.svg" alt="线路中间电容的互连结构"></p><p>从整个链路来看，时间常数里的 R 变了，这个 R 应该是两个并联之后的 25 Ω。</p><blockquote><p>「两个并联」指电容左右两段 50 Ω 传输线。</p><p>两端匹配、不考虑反射时，从电容节点看进去两边各是 50 Ω，并联就是 25 Ω。</p></blockquote><p>线路中间的容性负载也会对末端接收芯片的信号到达时间造成影响，同样是这个规律：</p><p>容值越大，延迟就越大；容值越小，延迟就越小。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794208751928-d66ea6ca-04f4-4322-89c1-89032ddc1169.svg" alt="线路中间电容不同容值的上升曲线"></p><h2 id="五每-pf-约-25-ps-的粗略规律" tabindex="-1">五、每 pF 约 25 ps 的粗略规律 <a class="header-anchor" href="#五每-pf-约-25-ps-的粗略规律" aria-label="Permalink to &quot;五、每 pF 约 25 ps 的粗略规律&quot;">​</a></h2><p>线路末端比较简单，就是一个典型的 RC 充电链路；用这个 RC 充电链路，电容两端电压上升时间的曲线可以很简单地算出来。</p><p>链路中间这个稍稍复杂一点。</p><p>有一个很粗略的结论：</p><p>如果是 50 Ω 阻抗控制的线，两端都是匹配的，就不考虑反射。</p><p>当信号上升时间远大于时间常数的时候，大概每 pF 电容 25 ps 的延迟，大概就这个量级。</p><p>但是要注意一个<strong>前提条件</strong>：信号上升时间远大于这个 RC 时间常数。</p><p>假如链路是 50 Ω 阻抗控制，电容在中间，电容是 1 pF，时间常数也是 25 ps；如果信号上升时间是 1 ns，那么电容每变化 1 pF，接收端信号中值电平的延迟时间大概就是 25 ps。</p><h2 id="六ddr-时序与输入电容偏差" tabindex="-1">六、DDR 时序与输入电容偏差 <a class="header-anchor" href="#六ddr-时序与输入电容偏差" aria-label="Permalink to &quot;六、DDR 时序与输入电容偏差&quot;">​</a></h2><blockquote><p>DDR：Double Data Rate，双倍数据速率。</p><p>DQ：Data Input/Output，数据输入/输出引脚（双向数据线）。</p><p>ODT：On-Die Termination，片内端接，芯片内部的终端匹配电阻。</p></blockquote><p>链路两端都做了匹配，不单单是排除反射的影响。考虑信号延迟时间、信号到达时间的时候，更多是在时序问题上。</p><p>比如说 DDR 接口，时序不满足，就是因为一个 line 里面这些信号边沿到达时间不一样，结果时序就会吃掉很多。</p><p>在 DDR 接口，比如说 DQ 那些数据线，DQ0 到 DQ7 这一组数据线，一个 line 是 8 比特。</p><p>这 8 个比特的 input buffer，它的输入电容不可能精确相等，比如有的是 0.6 pF，有的是 0.4 pF，同一个 line 里面不同比特的输入电容不同，信号边沿到达的时间也不一样，因为末端的电容对它是有影响的。</p><p>DDR 接口里，往往写数据的时候要有 ODT，ODT 的目的也是做一下阻抗的匹配。</p><p>末端电容不同，信号到达时间不一样。</p><p>假如 DQ0 和 DQ7 最大相差 2 pF，这边有可能就相差出十几 ps 或几十 ps 去了。DDR 接口速度非常高的时候，被吃掉十几个 ps 是很大的一个量。算过时序的时候应该能有体会，DDR 接口速率到 1600 以上的时候，时序余量很小很小，非常紧张。</p><h2 id="七fly-by-结构与常规仿真" tabindex="-1">七、Fly-by 结构与常规仿真 <a class="header-anchor" href="#七fly-by-结构与常规仿真" aria-label="Permalink to &quot;七、Fly-by 结构与常规仿真&quot;">​</a></h2><p>末端容性负载的不同对信号延迟的影响，最典型的应用场景对应着 DDR2 的数据 DQ 那组线。</p><p>链路中间的电容也会影响到接收端信号到达的时间，比较典型的是 DDR2、DDR3 地址控制命令那种 Fly-by 线。</p><p>DDR2 那一大堆地址线、控制线、命令线，不能保证每一个信号到达某一个芯片的时候，那个芯片的输入电容都是一样的；从工业上来说必然会有偏差，在工程上就是这样，所以边沿到达的时间一定跟这个输入电容有关。</p><p>DDR2 接口的波形有的时候会很乱，地址线、数据线、地址控制命令那一路线，眼图可能会比较差，其中有一项就包含了输入电容容值差的影响。</p><h2 id="八输入电容偏差的评估实例" tabindex="-1">八、输入电容偏差的评估实例 <a class="header-anchor" href="#八输入电容偏差的评估实例" aria-label="Permalink to &quot;八、输入电容偏差的评估实例&quot;">​</a></h2><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794227596452-9507ffe3-7ce0-494f-82eb-3844deea8a64.svg" alt="输入电容偏差消耗时间"></p><p>比如 DDR2 接口，这里评估了一条 DQ 数据线在某种特定情况下的容值差。</p><p>因为 DQ0 到 DQ7 是一组，各自的输入电容容值也不一样，仿真的时候，在 VREF 以这个电平来判断，大概是 7 ps；只是差着 0.4 pF，这个偏差就出来了。</p>',51)])])}const u=p(o,[["render",s]]);export{D as __pageData,u as default};
